css:
/* START - fix x button in contact overlay*/
@media only screen and (max-width: 1024px) {
    #modal-global-contact-us {
        div.contact-form{
            &__container {
                width: 100%;
            }
            &__close.close {
                color: #fff;
                opacity: 1;
            }
        }
    }
}
/* END - fix x button in contact overlay*/

/* START - contact overlay theme*/
#modal-global-contact-us div.input-container{
    input.lp-input,textarea{
        &:-webkit-autofill{
            &:focus {
            color: #000;
            }
            -webkit-text-fill-color: #000;
        }
        color: #000;
        border-color: #000;
    }
    span.input-icon{
        filter:invert(1);
    }
}
/* END - contact overlay theme*/

/*START - footer link theme and underline*/
footer#global-footer{
    a:not(.socials__item),.link,.footer-navigation__link{
        text-decoration: none;
        position: relative!important;
        color:#000!important;
        &:hover{
            color:#777!important;
            opacity:1!important;
        }
        &:before, &:after{
            transition: 0.4s;
            text-decoration: none!important;
            line-height: 1;
            content: "";
            height: 1px;
            position: absolute!important;
            bottom: 0;
            left: 0;
        }
        &:before {
            width: 100%!important;
            background-color: #ccc!important;
            opacity:1;
        }
        &:after{
            width: 0%!important;
            background-color: #000!important; 
        }
        &:hover:after{
            width: 100%!important;
        }
        @media only screen and (max-width: 1280px){
            overflow-wrap: anywhere;
            text-decoration: underline!important;
            white-space: normal!important;
                &:before {
                    background-color: transparent;
                    width: 0%!important;
                }
                &:after {
                    background-color: transparent;
                }
            &:hover:after{
                width: 0%!important;
            }
        }
    }
    div.site-footer__copy div:nth-child(2) a,.footer-navigation__link{
        padding-bottom:5px!important;
    }
}
/*END - footer link theme and underline-*/

/* start - make EHO and Realtor logo black */
#global-footer .site-footer__disclaimer {
    opacity: 1;
    color: #929395;
    &:after{
        background-color:#000;
        opacity: 1;
    }
}
/*end*/

/*START - adjust footer logo size*/
footer .site-footer__logo-container img.portrait {
    max-width: 268px;
    max-height: 100px;
}
/*END - adjust footer logo size*/

/* START - header nav theme*/
nav#global-navbar{
        /* START - default state - homepage header nav*/
    .header.theme-light{
        .header__hamburger{
            circle {
                fill: #fff;
            }
            svg rect{
                fill:#7782ac!important;
            }
        }
        ul.navigation li.navigation__item{
            a.navigation__link{
                color:#fff;
                &:hover{
                    color:#dedede!important;
                }
            }
            &:after {
                border-color: #fff;
            }
            .sub-nav__link {
                color: #000;
                background-color: #fff;
            }
            .sub-nav__link:hover {
                color: #FFF;
                background-color: #7782ac;
            }
            .navigation__link:after{
                background: #fff;
            }
        }
    }
    /* END- default state - homepage header nav*/

    /* START- default state - other pages header nav(property details+home val)*/
    .header{
        .header__hamburger{
            circle {
                fill: #7782ac;
            }
            svg rect{
                fill:#fff!important;
            }
        }
        ul.navigation li.navigation__item{
            a.navigation__link{
                color:#000;
                &:hover{
                    color:#777!important;
                }
            }
            &:after {
                border-color: #7782ac;
            }
            .sub-nav__link {
                color: #000;
                background-color: #fff;
            }
            .sub-nav__link:hover {
                color: #FFF!important;
                background-color: #7782ac;
            }
            .navigation__link:after{
                background: #7782ac;
            }
        }
    }
    /* END - default state - other pages header nav(property details+home val)*/

    /* START - scrolled state header nav in all pages(including homepage)*/
    &.scroll .header{
        background-color: #EBE7E0;
        .header__hamburger{
            circle {
                fill: #7782ac;
            }
            svg rect{
                fill:#fff!important;
            }
        }
        ul.navigation li.navigation__item{
            a.navigation__link{
                color:#000;
                &:hover{
                    color:#777!important;
                }
            }
            &:after {
                border-color: #7782ac;
            }
            .sub-nav__link {
                color: #000;
                background-color: #fff;
            }
            .sub-nav__link:hover {
                color: #FFF!important;
                background-color: #7782ac;
            }
            .navigation__link:after{
                background: #7782ac;
            }
        }
    }
    /* ENd - scrolled state header nav in all pages(including homepage)*/
}
/* END - header nav theme*/

/*START - increase logo size*/
@media only screen and (min-width:534px){
       nav#global-navbar .header__logo a.logo{
        width: 300px;
        height: 64px;
        max-width: 300px;
        & .logo__img {
            width: 300px;
            height: 64px;
        }
    } 
}
/*END- increase logo size*/

/*START - display dark logo on scrolled state */
nav#global-navbar.scroll {
    .header.theme-light .logo__img.light {
        display: none;
    }
    .header.theme-light .logo__img.dark {
        display: block;
    }
    .header.theme-auto .logo__img.light {
        display: none;
    }
    .header.theme-auto .logo__img.dark {
        display: block;
    }
}
/*END - display dark logo on scrolled state */

/*START - removing dash on all hyperlink*/
.hyperlink-style-1:before, .hyperlink-style-2:before {
    content: ""!important;
}
/*END - removing dash on all hyperlink*/

/*START - CTA icon color on mobile view */
div#global-mobile-contact .item{
    background-color:#EBE7E0;
    border: 2px solid #EBE7E0;
    color:#7C7A61;
    svg{
        fill:#7C7A61;
    }
    &:hover{
        background-color: #d3cfc9;
        border: 2px solid #d3cfc9;
        svg{
            fill:#7C7A61;
        }
        color:#7C7A61;
    }
}
/*END - CTA icon color on mobile view */

/*START - adding bg image to side menu*/
div#global-sidemenu.sidemenu .sidemenu__img {
background-image: url("https://res.cloudinary.com/luxuryp/images/mp82ncrklfupe2spig4k/side-menu");
}
/*START - adding bg image to side menu*/

/*START - Agent Properties*/
a.item{
    background-color: #f1f1f1;
    color:#000;
    h5{
        padding:10px 25px 0 35px;
    }
    p.bf1{
        padding:0px 25px 0 35px;
    }
    ul.bf2{
        padding:0 25px 20px 35px;

    }
