}
/*START - agent bio content theming*/

/*START - fix pagination*/
.lp-pagination.pagination-container .paginationjs .paginationjs-pages ul li a:after {
    border-right: 2px solid #b2b2b2;
    border-top: 2px solid #b2b2b2;
}
