        }
    }
}
/*END - home val steps(Local)*/

/*START - change dropdown color*/
.custom-select-menu .custom-select-content {
    color: #000;
    background-color: #fff;
    .custom-select-item:hover {
        color: #fff!important;
        background-color: #7782ac;
    }
}
/*END - change dropdown color*/

/*START - Make title one row*/
.lp-title-group {
    max-width: 100%;
}
/*END - Make title one row*/

/*Un-Itilicize Pre-Title*/
.opening-pretitle {
    font-style: normal;
}
/*end*/

/*Button style hover state color*/
.lp-btn.lp-btn--light.lp-btn--outline: hover {
    background: #fff;
    border-color: #fff;
    color: #041c32;
}
/*Button style end*/

/*Button search style color*/
div.container div.search-form button.search-button{
    background: #f1eee9;
    border-color: #f1eee9;
    color: #63614d;
    font-size: 14px;
    line-height: 1.3;
    font-weight: 600;
    border-radius: 0;
    font-family: var(--global-secondary-font-family-short, sans-serif);
    text-transform: uppercase;
    padding: 19px 25px;
    &:hover{
        background: #EBE7E0;
        border-color: #EBE7E0;
        color: #63614d;
    }
}
/*Button search style end*/

/*START - Add CA DRE bottom left corner of the Opening*/
div.opening-with-search .bottom-spacer:after {
    padding-top: 130px;
    content: "Client Name | CA DRE# 0000";
    position: absolute;
    margin-left: 50px;
}
/*END - CADRE bottom left corner of the Opening*/

/*START - theming*/
.popup-modal__input {
    filter: invert(1);
}
span.input-icon{
    filter: invert(1);
}
form.popup-modal__form div.form-group {
    padding: 100px;
}

/*START - page pagination*/
